			bytesToKZGProof(proofs[0]))
	}

	// Use batch verification for multiple blobs
	ckzgBlobs := make([]ckzg4844.Blob, len(blobs))
	ckzgCommitments := make([]ckzg4844.Bytes48, len(commitments))
